# Runtime paths for one NERSC profile, generated by nersc/configure_user.py.
# activate.sh and the profile's batch launcher source this file; edit it here
# if a location changes. Values are plain assignments: this file defines them.

# Checkout providing the workflow scripts and shared configuration.
export HIC_CODE_HOME={{CODE_HOME}}
# Installed software prefix (the conda environment the models were built into).
export HIC_SOFTWARE_ROOT={{SOFTWARE_ROOT}}
# GNU runtime module that run-events-wrapper loads on compute nodes; empty disables it.
export HIC_RUNTIME_GCC_MODULE={{RUNTIME_GCC_MODULE}}

# Campaign storage.
export HIC_RAW_ROOT={{RAW_ROOT}}
export HIC_CAMPAIGN_OUTPUT_ROOT={{OUTPUT_ROOT}}
export HIC_SURFACE_ARCHIVE_ROOT={{ARCHIVE_ROOT}}
# Source base stripped from event paths; keep fixed when handing off a campaign.
export HIC_SURFACE_ARCHIVE_BASE={{ARCHIVE_BASE}}
export HIC_EVENT_CACHE_LOCAL_ROOT={{CACHE_STAGING_ROOT}}
export HIC_EVENT_CACHE_CFS_ROOT={{CACHE_PUBLISHED_ROOT}}

# Read-only production physics data (see nersc/SETUP.md for the required layout).
export HIC_CFS_ROOT={{DATA_ROOT}}
export HIC_EOS_PCE_DIR=$HIC_CFS_ROOT/EOS/PCE/strange_30_10000
export HIC_IS3D_DATA_ROOT=$HIC_CFS_ROOT/iS3D
export HIC_IS3D_CONFIG=$HIC_IS3D_DATA_ROOT/iS3D_parameters.dat
export HIC_PDG_DIR=$HIC_IS3D_DATA_ROOT/PDG
export HIC_IS3D_PDG_DIR=$HIC_PDG_DIR
export HIC_IS3D_TABLE_DIR=$HIC_IS3D_DATA_ROOT/tables
export HIC_IS3D_DELTAF_DIR=$HIC_IS3D_DATA_ROOT/deltaf_coefficients/vh
export HIC_IS3D_CHOSEN_PARTICLES=$HIC_PDG_DIR/chosen_particles.dat
export HIC_CHARGE_DICT=$HIC_PDG_DIR/charge_dict.dat
export HIC_BARYON_DICT=$HIC_PDG_DIR/baryon_dict.dat
export HIC_PDG_MASS=$HIC_PDG_DIR/pdg_smash_pce.dat
# OO5360 nuclear configurations; an explicit export before sourcing wins.
export HIC_O16_NUCLEUS_TABLE="${HIC_O16_NUCLEUS_TABLE:-$HIC_CFS_ROOT/nuclear_tables/o16_nleft_o13.hdf5}"

# Model executables and per-event inputs.
export HIC_MUSIC_EXEC=$HIC_SOFTWARE_ROOT/bin/MUSIChydro
export HIC_IS3D_EXEC=$HIC_SOFTWARE_ROOT/bin/iS3D
export HIC_SMASH_EXEC=$HIC_SOFTWARE_ROOT/bin/smash
export HIC_SMASH_CONFIG=$HIC_CODE_HOME/config/config.yaml
export HIC_IS3D_OSCAR_SCRIPT=$HIC_CODE_HOME/models/iS3D/iS3D_OSCAR.py
export HIC_ZSTD_EXEC=zstd
